import java.util.Scanner;

public class Main {
    public static void share(int whole) {
        System.out.println("{w1}" + whole);
    }

    public static void share(double part) {
        System.out.println("{w2}" + part);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        share(n / 2);
        share(n / 2.0);
    }
}
